=# Material UI Compatibility Assessment

## Summary

**Compatibility Score:** {{
  (() => {
    const score = ($json.output || $json).summary?.compatibilityScore;

    return typeof score === "number"
      ? Math.round(score) + "%"
      : "Not available";
  })()
}}

**Customization Effort:** {{
  (() => {
    const effort = ($json.output || $json).summary?.customizationEffort;

    return effort === "none" ? "🟢 None" :
      effort === "minor" ? "🟡 Minor" :
      effort === "medium" ? "🟠 Medium" :
      effort === "high" ? "🔴 High" :
      "Not available";
  })()
}}

**Confidence:** {{
  (() => {
    const confidence = ($json.output || $json).summary?.confidence;

    return typeof confidence === "number"
      ? Math.round(confidence * 100) + "%"
      : "Not available";
  })()
}}

**Assessment:** {{
  ($json.output || $json).summary?.overallCompatibility ||
  "No compatibility summary available."
}}

---

## Recommended MUI Implementation

| Design area | Recommended MUI implementation | Customization |
|---|---|---|
{{
(() => {
  const data = $json.output || $json;
  const rows = [];

  const addRow = (target, strategy, level) => {
    if (!target || !strategy) return;

    rows.push({
      target: String(target).trim(),
      strategy: String(strategy).trim(),
      level: level || "none"
    });
  };

  (data.layoutMappings || []).forEach(m => {
    addRow(
      m.layoutId,
      (m.muiComponents || []).join(" + "),
      m.customizationLevel
    );
  });

  (data.elementMappings || []).forEach(m => {
    addRow(
      m.elementId,
      [m.muiComponent, m.variant]
        .filter(Boolean)
        .join(" — "),
      m.customizationLevel
    );
  });

  (data.groupMappings || []).forEach(m => {
    addRow(
      m.groupId,
      [m.muiContainerComponent, m.muiChildComponent]
        .filter(Boolean)
        .join(" + "),
      m.customizationLevel
    );
  });

  (data.semanticImplementationMappings || []).forEach(m => {
    addRow(
      m.semanticPatternName,
      (m.muiStrategy || []).join(" + "),
      m.customizationLevel
    );
  });

  const priority = {
    high: 4,
    medium: 3,
    minor: 2,
    none: 1
  };

  const levelLabel = level =>
    level === "none" ? "🟢 None" :
    level === "minor" ? "🟡 Minor" :
    level === "medium" ? "🟠 Medium" :
    "🔴 High";

  const seen = new Set();

  return rows
    .filter(row => {
      const key =
        row.target.toLowerCase() +
        "|" +
        row.strategy.toLowerCase();

      if (seen.has(key)) return false;

      seen.add(key);
      return true;
    })
    .sort(
      (a, b) =>
        (priority[b.level] || 0) -
        (priority[a.level] || 0)
    )
    .map(row =>
      "| " +
      row.target +
      " | `" +
      row.strategy.replace(/\|/g, "\\|") +
      "` | " +
      levelLabel(row.level) +
      " |"
    )
    .join("\n");
})()
}}

---

## Significant Customizations

{{
(() => {
  const data = $json.output || $json;
  const items = [];

  const addItem = (target, level, reason) => {
    if (
      !target ||
      !reason ||
      !["medium", "high"].includes(level)
    ) {
      return;
    }

    items.push({
      target: String(target).trim(),
      level,
      reason: String(reason).trim()
    });
  };

  (data.layoutMappings || []).forEach(m => {
    addItem(
      m.layoutId,
      m.customizationLevel,
      m.reason
    );
  });

  (data.elementMappings || []).forEach(m => {
    addItem(
      m.elementId,
      m.customizationLevel,
      m.reason
    );
  });

  (data.groupMappings || []).forEach(m => {
    addItem(
      m.groupId,
      m.customizationLevel,
      m.reason
    );
  });

  (data.semanticImplementationMappings || []).forEach(m => {
    addItem(
      m.semanticPatternName,
      m.customizationLevel,
      m.reason
    );
  });

  const priority = {
    high: 2,
    medium: 1
  };

  const levelLabel = level =>
    level === "medium"
      ? "🟠 Medium"
      : "🔴 High";

  const seen = new Set();

  const uniqueItems = items.filter(item => {
    const key =
      item.target.toLowerCase() +
      "|" +
      item.reason
        .toLowerCase()
        .replace(/\s+/g, " ")
        .trim();

    if (seen.has(key)) return false;

    seen.add(key);
    return true;
  });

  const rendered = uniqueItems
    .sort(
      (a, b) =>
        (priority[b.level] || 0) -
        (priority[a.level] || 0)
    )
    .map(item =>
      "- **" +
      item.target +
      "** — " +
      levelLabel(item.level) +
      "\n  " +
      item.reason
    )
    .join("\n\n");

  return rendered ||
    "No significant customization is required.";
})()
}}

---

## Accessibility Considerations

{{
(() => {
  const data = $json.output || $json;
  const notes = [];

  const accessibilityPattern =
    /aria-|accessible|accessibility|screen reader|keyboard|focus|heading|decorative|aria-pressed|aria-describedby|aria-hidden|role=/i;

  const collect = item => {
    const target =
      item.layoutId ||
      item.elementId ||
      item.groupId ||
      item.semanticPatternName ||
      "Implementation";

    const sources = [
      item.reason,
      ...(item.muiStrategy || [])
    ].filter(Boolean);

    const relevant = sources.filter(text =>
      accessibilityPattern.test(String(text))
    );

    if (!relevant.length) return;

    notes.push({
      target: String(target).trim(),
      text: relevant.join(" ")
    });
  };

  (data.layoutMappings || []).forEach(collect);
  (data.elementMappings || []).forEach(collect);
  (data.groupMappings || []).forEach(collect);
  (data.semanticImplementationMappings || []).forEach(collect);

  const seen = new Set();

  const uniqueNotes = notes.filter(note => {
    const key = note.text
      .toLowerCase()
      .replace(/\s+/g, " ")
      .trim();

    if (seen.has(key)) return false;

    seen.add(key);
    return true;
  });

  return uniqueNotes.length
    ? uniqueNotes
        .slice(0, 3)
        .map(note =>
          "- **" +
          note.target +
          ":** " +
          note.text
        )
        .join("\n")
    : "No specific accessibility considerations were identified.";
})()
}}

---

## Risks and Open Questions

{{
(() => {
  const warnings =
    ($json.output || $json)
      .customImplementationWarnings || [];

  const severityPriority = {
    high: 3,
    medium: 2,
    low: 1
  };

  const severityLabel = severity =>
    severity === "low" ? "🟡 Low" :
    severity === "medium" ? "🟠 Medium" :
    "🔴 High";

  const seen = new Set();

  const uniqueWarnings = warnings
    .filter(warning => {
      const target = String(
        warning.target || "Implementation"
      ).trim();

      const reason = String(
        warning.reason ||
        "Further clarification is required."
      ).trim();

      const key =
        target.toLowerCase() +
        "|" +
        reason.toLowerCase();

      if (seen.has(key)) return false;

      seen.add(key);
      return true;
    })
    .sort(
      (a, b) =>
        (severityPriority[b.severity] || 0) -
        (severityPriority[a.severity] || 0)
    );

  return uniqueWarnings.length
    ? uniqueWarnings
        .map(warning =>
          "- **" +
          (warning.target || "Implementation") +
          "** — " +
          severityLabel(warning.severity) +
          "\n  " +
          (
            warning.reason ||
            "Further clarification is required."
          )
        )
        .join("\n\n")
    : "No major implementation risks were identified.";
})()
}}

