const semanticInput = $input.first().json;
const semanticRoot = semanticInput.output || semanticInput;

// Resolve the canonical UI model from whichever input adapter executed.
// This is the only source-specific boundary; everything below uses one schema.
let visualRoot = {};

const tryNode = (nodeName) => {
  try {
    const nodeJson = $(nodeName).first()?.json || {};
    const raw = nodeJson.output || nodeJson;

    if (Array.isArray(raw)) {
      const text = raw[0]?.content?.[0]?.text || "";
      if (!text) return null;
      return JSON.parse(text.replace(/```json|```/g, "").trim());
    }

    if (typeof raw === "string") {
      return JSON.parse(raw.replace(/```json|```/g, "").trim());
    }

    if (raw?.content?.[0]?.text) {
      return JSON.parse(
        raw.content[0].text.replace(/```json|```/g, "").trim()
      );
    }

    return raw && typeof raw === "object" ? raw : null;
  } catch (e) {
    return null;
  }
};

// Prefer the already-normalized Figma model when that route executed;
// otherwise use the screenshot analyzer's canonical JSON.
visualRoot =
  tryNode("Normalize Figma Structure") ||
  tryNode("Analyze Design Screenshot") ||
  {};

const summaryProjection = {
  layout: {
    overallStructure: visualRoot.layout?.overallStructure || "Not specified",
    regions: visualRoot.layout?.regions || [],
    alignment: visualRoot.layout?.alignment,
    spacing: visualRoot.layout?.spacing
  },

  groups: (visualRoot.groups || []).map(g => ({
    id: g.id,
    type: g.type,
    children: g.children || []
  })),

  elements: (visualRoot.elements || []).map(el => ({
    id: el.id,
    role: el.visualRole,
    text: el.visibleText || undefined,
    state: el.state || undefined
  })).filter(el => el.role),

  separators: (visualRoot.separators || []).map(sep => ({
    id: sep.id,
    orientation: sep.orientation,
    continuity: sep.continuity,
    associatedGroup: sep.associatedGroup,
    associatedIcon: sep.associatedIcon
  })),

  repeatedStructures: (visualRoot.repeatedStructures || []).map(rep => ({
    id: rep.id,
    itemType: rep.itemType,
    count: rep.visibleItems?.length || rep.itemCount || 0,
    visibleTextList: rep.visibleItems || [],
    interactionPattern: rep.interactionPattern,
    sharedStyle: rep.sharedStyle
  })),

  semanticPatterns: (semanticRoot.semanticPatterns || []).map(pattern => ({
    name: pattern.name,
    type: pattern.type,
    importance: pattern.importance,
    muiImplications: pattern.muiImplications || []
  })),

  missingOrAmbiguousPatterns: (semanticRoot.missingOrAmbiguousPatterns || [])
    .filter(p => !p.description?.toLowerCase().includes("count"))
    .filter(p => !p.reason?.toLowerCase().includes("count")),

  source: visualRoot._canonicalMeta?.source ||
    (tryNode("Normalize Figma Structure") ? "figma" : "screenshot")
};

return [{ json: summaryProjection }];

const item = $input.first();
const figmaUrl = item.json.figmaUrl;

const match = figmaUrl.match(/\/design\/([a-zA-Z0-9]+)/);
const fileKey = match ? match[1] : null;

if (!fileKey) {
  throw new Error("Could not extract Figma file key from URL");
}

return [{
  json: {
    figmaUrl,
    fileKey
  }
}];

const item = $input.first();
const figmaData = item.json;

function extractNodes(node, depth = 0) {
  const result = {
    id: node.id,
    name: node.name,
    type: node.type,
    depth
  };

  if (node.characters) {
    result.text = node.characters;
  }

  if (node.layoutMode) {
    result.layoutMode = node.layoutMode;
  }

  if (node.primaryAxisAlignItems) {
    result.alignment = node.primaryAxisAlignItems;
  }

  if (node.itemSpacing !== undefined) {
    result.spacing = node.itemSpacing;
  }

  if (node.children && node.children.length > 0) {
    result.children = node.children.map(child => extractNodes(child, depth + 1));
  }

  return result;
}

const document = figmaData.document || {};
const pages = document.children || [];

const frames = [];
const textElements = [];
const layoutGroups = [];
const autoLayoutContainers = [];

function traverse(node) {
  if (node.type === "FRAME") {
    frames.push({
      id: node.id,
      name: node.name,
      layoutMode: node.layoutMode,
      children: node.children ? node.children.length : 0
    });
  }

  if (node.type === "TEXT") {
    textElements.push({
      id: node.id,
      text: node.characters || node.name,
      name: node.name
    });
  }

  if (node.layoutMode === "VERTICAL" || node.layoutMode === "HORIZONTAL") {
    autoLayoutContainers.push({
      id: node.id,
      name: node.name,
      layoutMode: node.layoutMode,
      spacing: node.itemSpacing,
      alignment: node.primaryAxisAlignItems
    });
  }

  if (node.type === "GROUP") {
    layoutGroups.push({
      id: node.id,
      name: node.name,
      children: node.children ? node.children.length : 0
    });
  }

  if (node.children) {
    node.children.forEach(child => traverse(child));
  }
}

pages.forEach(page => traverse(page));

const normalized = {
  layout: {
    overallStructure: frames.length > 0 ? frames[0].layoutMode || "unknown" : "unknown",
    regions: frames.map(f => f.name),
    spacing: autoLayoutContainers.length > 0 ? autoLayoutContainers[0].spacing : "unknown",
    alignment: autoLayoutContainers.length > 0 ? autoLayoutContainers[0].alignment : "unknown",
    responsiveHints: ""
  },
  groups: layoutGroups.map(g => ({
    id: g.id,
    type: "layout-group",
    children: []
  })),
  elements: textElements.map(el => ({
    id: el.id,
    visualRole: "text",
    visibleText: el.text,
    state: "",
    interactionHint: "",
    confidence: 0.9
  })),
  separators: [],
  repeatedStructures: [],
  relationships: [],
  customPatterns: []
};

return [{
  json: {
    ...normalized,
    _canonicalMeta: {
      source: "figma",
      schemaVersion: "1"
    }
  }
}];
